import { readFileSync } from 'node:fs';
/** Exact pinned baseline DDL, never regenerated by a test or widened to ignore unrelated changes. */
const pinned = JSON.parse(readFileSync(new URL('../fixtures/historical-skill-schema-b85625ad.json', import.meta.url), 'utf8')) as Record<string, { historicalSql?: string; currentSql: string }>;

/** Only the known empty import addition and null ancestry are projected for explicit historic scenario captures. */
export function historicalSkillImportState(name: string, sql: string, rows: Record<string, unknown>[]): { sql: string; rows: Record<string, unknown>[] } | null {
  const schema = pinned[name];
  if (!schema || sql !== schema.currentSql) return { sql, rows };
  if (name === 'shannon_skill_imports') {
    if (rows.length) throw new Error('HISTORICAL_SKILL_IMPORT_WRITTEN');
    return null;
  }
  if (rows.some(row => row.provenance_json !== null || row.made_by === 'operator_authored' || row.actor === 'operator_authored')) throw new Error('HISTORICAL_SKILL_IMPORT_ANCESTRY_WRITTEN');
  return { sql: schema.historicalSql!, rows: rows.map(({ provenance_json: _empty, ...row }) => row) };
}
